<template><span class="portrait" :class="character?.faction"><img v-if="character?.image && !failed" :src="character.image" :alt="character.name" @error="failed=true"><span v-else>{{character?.name?.[0] || '?'}}</span></span></template>
<script setup>import {ref,watch} from 'vue'; const props=defineProps({character:Object});const failed=ref(false);watch(()=>props.character?.image,()=>failed.value=false);</script>
